import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem104 qualifica alegações sem alterar dados operacionais',()=>{for(const [n,titulo,expected] of [["5287633095","Câmera de Segurança Babá Eletrônica Ip Wifi 1080p Full Hd Visão Noturna Ideal Para Bebê Crianças Idosos Pets Áudio Bidirecional Kateluo","Câmera Wi-Fi Kateluo — 1080p e áudio bidirecional anunciados"],["5299235149","Kit Instrumento Musical Bandinha Infantil Presente +4 Anos","Kit Instrumento Musical Bandinha Infantil Presente +4 Anos"],["5336183061","Inversor Veicular IF-378 350W 12V para com USB e LED","Inversor veicular IF-378 — 12 V, até 350 W anunciados"]]){const p={id:'mlMLB'+n,titulo,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar',link:'https://produto.mercadolivre.com.br/MLB-'+n},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.link,p.link);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).comentario,p.comentario);}});
